import axios from 'axios'
import { React, useEffect, useState } from 'react'
import { Link } from "react-router-dom"

const Members = () => {
    const [members, setMembers] = useState([])

    useEffect(() => {
        const fetchAllMembers = async () => {
            try {
                const res = await axios.get("http://localhost:8800")
                console.log(res)
                
            } catch(err) {
                console.log(err)
            }
        }
        fetchAllMembers()
    }, [])

    const membershipStat = async (membership) => {
        if (membership) {
            return "Yes"
        }
        return "No"
    }

    const handleDelete = async (id) => {
        try {
            await axios.delete("http://localhost:8800" + id)
            window.location.reload()
        } catch (err) {
            console.log(err)
        }
    }

    return ( 
        <div>
            <h1>Members List</h1>

            <div className="members">
                {members.map(member => (
                    <div className="member" key={member.id}>
                        {member.name && <img src={member.name} alt="" />}
                        <h2>Member name: {member.name}</h2>
                        <h2>Membership: {membershipStat(member.membership)}</h2>
                        <h2>Age: {member.age}</h2>
                        <button className="delete" onClick={() => handleDelete(member.id)}>Delete</button>
                    </div>
                ))}
            </div>
            <button>
                <Link to="/add">Add new member</Link>
            </button>
        </div>
    )
}

export default Members
